    pub bearer: Option<String>,
    /// The `Sec-WebSocket-Key` of a request that asks to upgrade to a
    /// WebSocket; the frame answers [`SUBSCRIBED`] to accept it.
    pub upgrade: Option<String>,
}

impl RemoteRequest {
